create table public.inventory_imports(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null references public.projects(id),actor_id uuid not null references auth.users(id),
 mode text not null check(mode in('create_only','update_existing','create_and_update')),status text not null check(status in('validated','invalid','confirming','completed','failed','expired')),
 operation_id uuid not null,payload_hash text not null,row_count integer not null,new_count integer not null default 0,update_count integer not null default 0,unchanged_count integer not null default 0,warning_count integer not null default 0,error_count integer not null default 0,
 expires_at timestamptz not null,confirmed_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),unique(actor_id,operation_id)
);
create table public.inventory_import_errors(id bigint generated always as identity primary key,import_id uuid not null references public.inventory_imports(id),row_number integer not null,column_name text,code text not null,message text not null,severity text not null check(severity in('warning','error')),masked_value text,classification text not null check(classification in('new','update','unchanged','warning','error')));
create index inventory_imports_project_created_idx on public.inventory_imports(project_id,created_at desc,id);create index inventory_import_errors_import_idx on public.inventory_import_errors(import_id,row_number,id);
alter table public.inventory_imports enable row level security;alter table public.inventory_import_errors enable row level security;
revoke all on public.inventory_imports,public.inventory_import_errors from public,anon,authenticated;grant select on public.inventory_imports,public.inventory_import_errors to authenticated;
create policy "managers read imports" on public.inventory_imports for select to authenticated using(private.can_manage_project(organization_id));
create policy "managers read import errors" on public.inventory_import_errors for select to authenticated using(exists(select 1 from public.inventory_imports i where i.id=import_id and private.can_manage_project(i.organization_id)));

create function private.import_hash(p_rows jsonb) returns text language sql immutable set search_path='' as $$select encode(extensions.digest(convert_to(p_rows::text,'UTF8'),'sha256'),'hex')$$;
create function private.import_error(p_import uuid,p_row int,p_column text,p_code text,p_message text,p_class text default 'error') returns void language sql security definer set search_path='' as $$insert into public.inventory_import_errors(import_id,row_number,column_name,code,message,severity,classification)values(p_import,p_row,p_column,p_code,p_message,'error',p_class)$$;

create function public.admin_preview_inventory_import(p_project_id uuid,p_mode text,p_rows jsonb,p_operation_id uuid,p_payload_bytes integer)
returns public.inventory_imports language plpgsql security definer set search_path='' as $$
declare p public.projects;i public.inventory_imports;r jsonb;n int=0;uid uuid;b uuid;f uuid;t uuid;ver bigint;errors int=0;news int=0;updates int=0;unchanged int=0;changed boolean;seen_codes text[]='{}';
begin perform private.require_active_user();select * into p from public.projects where id=p_project_id;if not found then perform private.raise_admin_error('not_found');end if;perform private.require_project_manager(p.organization_id);
 select * into i from public.inventory_imports where actor_id=auth.uid() and operation_id=p_operation_id;if found then return i;end if;
 if p.status='archived' or p_mode not in('create_only','update_existing','create_and_update') or jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows) not between 1 and 1000 or p_payload_bytes not between 1 and 5242880 then perform private.raise_admin_error('invalid_input');end if;
 insert into public.inventory_imports(organization_id,project_id,actor_id,mode,status,operation_id,payload_hash,row_count,expires_at)values(p.organization_id,p.id,auth.uid(),p_mode,'validated',p_operation_id,private.import_hash(p_rows),jsonb_array_length(p_rows),transaction_timestamp()+interval '30 minutes')returning * into i;
 for r in select value from jsonb_array_elements(p_rows)loop n=n+1;uid=null;b=null;f=null;t=null;ver=null;changed=false;
  if jsonb_typeof(r)<>'object' or btrim(coalesce(r->>'unit_code',''))='' then perform private.import_error(i.id,n,'unit_code','required','Código da unidade obrigatório.');errors=errors+1;continue;end if;
  if r->>'unit_code'=any(seen_codes) then perform private.import_error(i.id,n,'unit_code','duplicate_in_file','Código repetido no arquivo.');errors=errors+1;continue;end if;seen_codes=array_append(seen_codes,r->>'unit_code');
  select x.id,x.version into uid,ver from public.units x where x.project_id=p.id and x.code=r->>'unit_code';
  select x.id into b from public.buildings x where x.project_id=p.id and x.code=r->>'building_code' and x.active;
  select x.id into f from public.floors x where x.building_id=b and x.code=r->>'floor_code' and x.active;
  select x.id into t from public.unit_types x where x.project_id=p.id and x.code=r->>'unit_type_code' and x.active;
  if b is null or f is null or t is null then perform private.import_error(i.id,n,'structure','invalid_reference','Edifício, pavimento ou tipologia inválido.');errors=errors+1;continue;end if;
  if coalesce(r->>'orientation','') not in('north','northeast','east','southeast','south','southwest','west','northwest') or coalesce(r->>'parking_spaces','')!~'^\d+$' or coalesce(r->>'currency','')!~'^[A-Z]{3}$' or (nullif(r->>'price','') is not null and r->>'price'!~'^\d+(\.\d+)?$') or (nullif(r->>'published','') is not null and r->>'published' not in('true','false')) or (nullif(r->>'expected_version','') is not null and r->>'expected_version'!~'^\d+$') then perform private.import_error(i.id,n,'values','invalid_input','Valores estruturais inválidos.');errors=errors+1;continue;end if;
  if uid is null then if p_mode='update_existing' then perform private.import_error(i.id,n,'unit_code','not_found','Unidade não encontrada.');errors=errors+1;continue;end if;if p.status<>'draft' and nullif(r->>'status','') is not null then perform private.import_error(i.id,n,'status','commercial_change_forbidden','Estado inicial permitido somente em rascunho.');errors=errors+1;continue;end if;if p.status='draft' and coalesce(nullif(r->>'status',''),'available') not in('available','reserved','sold') then perform private.import_error(i.id,n,'status','invalid_input','Estado inicial inválido.');errors=errors+1;continue;end if;news=news+1;insert into public.inventory_import_errors(import_id,row_number,code,message,severity,classification)values(i.id,n,'new','Nova unidade','warning','new');
  else if p_mode='create_only' then perform private.import_error(i.id,n,'unit_code','duplicate_code','Unidade já existe.');errors=errors+1;continue;end if;if nullif(r->>'expected_version','') is null or (r->>'expected_version')::bigint<>ver then perform private.import_error(i.id,n,'expected_version','version_conflict','Versão divergente.');errors=errors+1;continue;end if;
   if p.status<>'draft' and ((nullif(r->>'price','') is not null and (r->>'price')::numeric is distinct from (select price_brl from public.units where id=uid)) or (nullif(r->>'status','') is not null and r->>'status' is distinct from (select status from public.units where id=uid)) or (nullif(r->>'published','') is not null and (r->>'published')::boolean is distinct from (select published from public.units where id=uid))) then perform private.import_error(i.id,n,'commercial','commercial_change_forbidden','Alteração comercial exige RPC específica.');errors=errors+1;continue;end if;
   select (building_id is distinct from b or floor_id is distinct from f or unit_type_id is distinct from t or external_reference is distinct from nullif(r->>'external_reference','') or orientation is distinct from r->>'orientation' or view_type is distinct from nullif(r->>'view_type','') or sun_exposure is distinct from nullif(r->>'solar_exposure','') or parking_spaces is distinct from (r->>'parking_spaces')::int or currency is distinct from r->>'currency' or (p.status='draft' and nullif(r->>'price','') is not null and price_brl is distinct from (r->>'price')::numeric) or (p.status='draft' and nullif(r->>'status','') is not null and status is distinct from r->>'status') or (p.status='draft' and nullif(r->>'published','') is not null and published is distinct from (r->>'published')::boolean)) into changed from public.units where id=uid;if changed then updates=updates+1;insert into public.inventory_import_errors(import_id,row_number,code,message,severity,classification)values(i.id,n,'update','Unidade será atualizada','warning','update');else unchanged=unchanged+1;insert into public.inventory_import_errors(import_id,row_number,code,message,severity,classification)values(i.id,n,'unchanged','Sem alterações','warning','unchanged');end if;
  end if;
 end loop;
 update public.inventory_imports set status=case when errors>0 then'invalid'else'validated'end,new_count=news,update_count=updates,unchanged_count=unchanged,error_count=errors where id=i.id returning * into i;return i;
exception when invalid_text_representation or numeric_value_out_of_range then update public.inventory_imports set status='invalid',error_count=error_count+1 where id=i.id returning * into i;return i;end$$;

create function public.admin_get_inventory_import(p_import_id uuid) returns table(id uuid,project_id uuid,mode text,status text,payload_hash text,row_count integer,new_count integer,update_count integer,unchanged_count integer,warning_count integer,error_count integer,expires_at timestamptz,completed_at timestamptz)language plpgsql stable security definer set search_path='' as $$declare i public.inventory_imports;begin perform private.require_active_user();select * into i from public.inventory_imports where inventory_imports.id=p_import_id;if not found or not private.can_manage_project(i.organization_id) then perform private.raise_admin_error('not_found');end if;return query select i.id,i.project_id,i.mode,i.status,i.payload_hash,i.row_count,i.new_count,i.update_count,i.unchanged_count,i.warning_count,i.error_count,i.expires_at,i.completed_at;end$$;
create function public.admin_list_inventory_imports(p_project_id uuid) returns setof public.inventory_imports language plpgsql stable security definer set search_path='' as $$declare org uuid;begin select organization_id into org from public.projects where id=p_project_id;if not found or not private.can_manage_project(org) then perform private.raise_admin_error('not_found');end if;return query select * from public.inventory_imports where project_id=p_project_id order by created_at desc,id;end$$;

create function public.admin_confirm_inventory_import(p_import_id uuid,p_operation_id uuid,p_rows jsonb,p_expected_hash text)
returns public.inventory_imports language plpgsql security definer set search_path='' as $$declare i public.inventory_imports;p public.projects;r jsonb;uid uuid;b uuid;f uuid;t uuid;ver bigint;n int=0;begin perform private.require_active_user();select * into i from public.inventory_imports where id=p_import_id for update;if not found or i.actor_id<>auth.uid() or not private.can_manage_project(i.organization_id) then perform private.raise_admin_error('not_found');end if;if i.status='completed' and i.operation_id=p_operation_id then return i;end if;if i.status<>'validated' or i.expires_at<=now() or i.operation_id<>p_operation_id or private.import_hash(p_rows)<>i.payload_hash or p_expected_hash<>i.payload_hash then perform private.raise_admin_error(case when i.expires_at<=now() then'import_expired'else'invalid_input'end);end if;perform pg_advisory_xact_lock(hashtextextended(i.project_id::text,0));select * into p from public.projects where id=i.project_id for update;if p.status='archived' then perform private.raise_admin_error('invalid_transition');end if;update public.inventory_imports set status='confirming',confirmed_at=now() where id=i.id;
 for r in select value from jsonb_array_elements(p_rows)loop n=n+1;select id into b from public.buildings where project_id=p.id and code=r->>'building_code' and active for update;select id into f from public.floors where building_id=b and code=r->>'floor_code' and active for update;select id into t from public.unit_types where project_id=p.id and code=r->>'unit_type_code' and active for update;select id,version into uid,ver from public.units where project_id=p.id and code=r->>'unit_code' for update;if b is null or f is null or t is null then perform private.raise_admin_error('version_conflict');end if;
  if uid is null then if i.mode='update_existing' then perform private.raise_admin_error('version_conflict');end if;insert into public.units(id,project_id,building_id,floor_id,unit_type_id,code,external_reference,status,price_brl,parking_spaces,orientation,view_type,sun_exposure,model_object_id,published,currency)values(gen_random_uuid(),p.id,b,f,t,r->>'unit_code',nullif(r->>'external_reference',''),case when p.status='draft' then coalesce(nullif(r->>'status',''),'available')else'available'end,case when p.status='draft' then nullif(r->>'price','')::numeric else null end,(r->>'parking_spaces')::int,r->>'orientation',nullif(r->>'view_type',''),nullif(r->>'solar_exposure',''),'UNMAPPED_'||gen_random_uuid(),case when p.status='draft' then coalesce((r->>'published')::boolean,false)else false end,r->>'currency')returning id into uid;perform private.audit_structure(i.organization_id,p.id,'unit',uid,'unit.imported_initial',null,jsonb_build_object('unit_code',r->>'unit_code','initial_status',case when p.status='draft'then coalesce(r->>'status','available')else'available'end,'import_id',i.id));
  else if nullif(r->>'expected_version','') is null or (r->>'expected_version')::bigint<>ver then perform private.raise_admin_error('version_conflict');end if;update public.units set building_id=b,floor_id=f,unit_type_id=t,external_reference=nullif(r->>'external_reference',''),orientation=r->>'orientation',view_type=nullif(r->>'view_type',''),sun_exposure=nullif(r->>'solar_exposure',''),currency=r->>'currency',parking_spaces=(r->>'parking_spaces')::int,version=version+1 where id=uid;perform private.audit_structure(i.organization_id,p.id,'unit',uid,'unit.imported_structure',null,jsonb_build_object('unit_code',r->>'unit_code','import_id',i.id));end if;
 end loop;update public.inventory_imports set status='completed',completed_at=now() where id=i.id returning * into i;perform private.audit_structure(i.organization_id,i.project_id,'project',i.project_id,'inventory_import.completed',null,jsonb_build_object('import_id',i.id,'rows',i.row_count,'new',i.new_count,'updated',i.update_count,'unchanged',i.unchanged_count,'payload_hash',i.payload_hash,'operation_id',i.operation_id));return i;end$$;

revoke all on function private.import_hash(jsonb),private.import_error(uuid,integer,text,text,text,text) from public,anon,authenticated;
revoke all on function public.admin_preview_inventory_import(uuid,text,jsonb,uuid,integer),public.admin_get_inventory_import(uuid),public.admin_confirm_inventory_import(uuid,uuid,jsonb,text),public.admin_list_inventory_imports(uuid) from public,anon,authenticated,service_role;
grant execute on function public.admin_preview_inventory_import(uuid,text,jsonb,uuid,integer),public.admin_get_inventory_import(uuid),public.admin_confirm_inventory_import(uuid,uuid,jsonb,text),public.admin_list_inventory_imports(uuid) to authenticated;

-- Confirmation deliberately repeats all mutable checks: the dry-run is a preview,
-- never an authorization cache. The project lock serializes imports per project.
create or replace function public.admin_confirm_inventory_import(p_import_id uuid,p_operation_id uuid,p_rows jsonb,p_expected_hash text)
returns public.inventory_imports language plpgsql security definer set search_path='' as $$
declare i public.inventory_imports;p public.projects;r jsonb;u public.units;b uuid;f uuid;t uuid;n int=0;changed boolean;new_status text;new_price numeric;new_published boolean;
begin
 perform private.require_active_user();
 select * into i from public.inventory_imports where id=p_import_id for update;
 if not found or i.actor_id<>auth.uid() or not private.can_manage_project(i.organization_id) then perform private.raise_admin_error('not_found');end if;
 if i.status='completed' and i.operation_id=p_operation_id then return i;end if;
 if i.expires_at<=now() then update public.inventory_imports set status='expired' where id=i.id;perform private.raise_admin_error('import_expired');end if;
 if i.status<>'validated' or i.operation_id<>p_operation_id or jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)<>i.row_count or private.import_hash(p_rows)<>i.payload_hash or p_expected_hash<>i.payload_hash then perform private.raise_admin_error('invalid_input');end if;
 perform pg_advisory_xact_lock(hashtextextended(i.project_id::text,0));
 select * into p from public.projects where id=i.project_id for update;
 if p.status='archived' then perform private.raise_admin_error('invalid_transition');end if;
 update public.inventory_imports set status='confirming',confirmed_at=now() where id=i.id;
 for r in select value from jsonb_array_elements(p_rows) loop
  n=n+1;b=null;f=null;t=null;u=null;
  if btrim(coalesce(r->>'unit_code',''))='' or coalesce(r->>'orientation','') not in('north','northeast','east','southeast','south','southwest','west','northwest') or coalesce(r->>'currency','')!~'^[A-Z]{3}$' or coalesce(r->>'parking_spaces','')!~'^\d+$' then perform private.raise_admin_error('invalid_input');end if;
  select id into b from public.buildings where project_id=p.id and code=r->>'building_code' and active for update;
  select id into f from public.floors where building_id=b and code=r->>'floor_code' and active for update;
  select id into t from public.unit_types where project_id=p.id and code=r->>'unit_type_code' and active for update;
  select * into u from public.units where project_id=p.id and code=r->>'unit_code' for update;
  if b is null or f is null or t is null then perform private.raise_admin_error('version_conflict');end if;
  if u.id is null then
   if i.mode='update_existing' then perform private.raise_admin_error('version_conflict');end if;
   if nullif(r->>'price','') is not null and (r->>'price' !~ '^\d+(\.\d+)?$' or (r->>'price')::numeric<0) then perform private.raise_admin_error('invalid_input');end if;
   if p.status='draft' and coalesce(nullif(r->>'status',''),'available') not in('available','reserved','sold') then perform private.raise_admin_error('invalid_input');end if;
   if nullif(r->>'published','') is not null and r->>'published' not in('true','false') then perform private.raise_admin_error('invalid_input');end if;
   insert into public.units(id,project_id,building_id,floor_id,unit_type_id,code,external_reference,status,price_brl,parking_spaces,orientation,view_type,sun_exposure,model_object_id,published,currency)
   values(gen_random_uuid(),p.id,b,f,t,r->>'unit_code',nullif(r->>'external_reference',''),case when p.status='draft' then coalesce(nullif(r->>'status',''),'available') else 'available' end,case when p.status='draft' then nullif(r->>'price','')::numeric else null end,(r->>'parking_spaces')::int,r->>'orientation',nullif(r->>'view_type',''),nullif(r->>'solar_exposure',''),'UNMAPPED_'||gen_random_uuid(),case when p.status='draft' then coalesce(nullif(r->>'published','')::boolean,false) else false end,r->>'currency') returning * into u;
   perform private.audit_structure(i.organization_id,p.id,'unit',u.id,'unit.imported_initial',null,jsonb_build_object('unit_code',u.code,'initial_status',u.status,'import_id',i.id));
  else
   if i.mode='create_only' or nullif(r->>'expected_version','') is null or r->>'expected_version'!~'^\d+$' or (r->>'expected_version')::bigint<>u.version then perform private.raise_admin_error('version_conflict');end if;
   if p.status<>'draft' and ((nullif(r->>'price','') is not null and (r->>'price')::numeric is distinct from u.price_brl) or (nullif(r->>'status','') is not null and r->>'status' is distinct from u.status) or (nullif(r->>'published','') is not null and (r->>'published')::boolean is distinct from u.published)) then perform private.raise_admin_error('invalid_transition');end if;
   new_price=case when p.status='draft' and nullif(r->>'price','') is not null then (r->>'price')::numeric else u.price_brl end;
   new_status=case when p.status='draft' and nullif(r->>'status','') is not null then r->>'status' else u.status end;
   new_published=case when p.status='draft' and nullif(r->>'published','') is not null then (r->>'published')::boolean else u.published end;
   if new_status not in('available','reserved','sold') and p.status='draft' then perform private.raise_admin_error('invalid_input');end if;
   changed=u.building_id is distinct from b or u.floor_id is distinct from f or u.unit_type_id is distinct from t or u.external_reference is distinct from nullif(r->>'external_reference','') or u.orientation is distinct from r->>'orientation' or u.view_type is distinct from nullif(r->>'view_type','') or u.sun_exposure is distinct from nullif(r->>'solar_exposure','') or u.currency is distinct from r->>'currency' or u.parking_spaces is distinct from (r->>'parking_spaces')::int or u.price_brl is distinct from new_price or u.status is distinct from new_status or u.published is distinct from new_published;
   if changed then
    update public.units set building_id=b,floor_id=f,unit_type_id=t,external_reference=nullif(r->>'external_reference',''),orientation=r->>'orientation',view_type=nullif(r->>'view_type',''),sun_exposure=nullif(r->>'solar_exposure',''),currency=r->>'currency',parking_spaces=(r->>'parking_spaces')::int,price_brl=new_price,status=new_status,published=new_published,reserved_by=case when new_status='reserved' then reserved_by else null end,reserved_at=case when new_status='reserved' then reserved_at else null end,reserved_until=case when new_status='reserved' then reserved_until else null end,version=version+1 where id=u.id;
    perform private.audit_structure(i.organization_id,p.id,'unit',u.id,'unit.imported_structure',jsonb_build_object('version',u.version),jsonb_build_object('unit_code',u.code,'version',u.version+1,'import_id',i.id));
   end if;
  end if;
 end loop;
 update public.inventory_imports set status='completed',completed_at=now() where id=i.id returning * into i;
 perform private.audit_structure(i.organization_id,i.project_id,'project',i.project_id,'inventory_import.completed',null,jsonb_build_object('import_id',i.id,'rows',i.row_count,'new',i.new_count,'updated',i.update_count,'unchanged',i.unchanged_count,'payload_hash',i.payload_hash,'operation_id',i.operation_id));
 return i;
exception when unique_violation or check_violation or invalid_text_representation or numeric_value_out_of_range then perform private.raise_admin_error('invalid_input');return null;
end$$;

-- SQL boolean logic must treat an ownerless imported reservation as not owned;
-- `not (... or null)` would otherwise evaluate to null and skip the denial.
create or replace function public.admin_change_unit_status(p_unit_id uuid,p_expected_version bigint,p_expected_status text,p_new_status text,p_reason text)
returns public.units language plpgsql security definer set search_path='' as $$
declare v_unit public.units;v_org_id uuid;v_actor uuid:=auth.uid();v_is_admin boolean;v_is_seller boolean;v_action text:='unit.status_changed';v_old_values jsonb;
begin
 if v_actor is null then perform private.raise_admin_error('forbidden');end if;if not private.is_active_user() then perform private.raise_admin_error('inactive_user');end if;
 if p_expected_version is null or p_expected_version<1 or p_expected_status is null or p_new_status is null or btrim(coalesce(p_reason,''))='' then perform private.raise_admin_error('invalid_input');end if;
 select u.* into v_unit from public.units u join public.projects p on p.id=u.project_id where u.id=p_unit_id and private.has_organization_access(p.organization_id) for update of u;
 if not found then perform private.raise_admin_error('not_found');end if;select p.organization_id into v_org_id from public.projects p where p.id=v_unit.project_id;
 v_is_admin:=private.has_organization_role(v_org_id,array['organization_admin']);v_is_seller:=private.has_organization_role(v_org_id,array['seller']);
 if not(v_is_admin or v_is_seller)then perform private.raise_admin_error('forbidden');end if;if v_unit.version<>p_expected_version then perform private.raise_admin_error('version_conflict');end if;if v_unit.status<>p_expected_status then perform private.raise_admin_error('status_conflict');end if;
 if not coalesce((v_is_admin and(v_unit.status,p_new_status)in(('available','reserved'),('reserved','available'),('reserved','sold'),('available','sold'),('sold','available')))or(v_is_seller and((v_unit.status='available'and p_new_status='reserved')or(v_unit.status='reserved'and p_new_status='available'and coalesce(v_unit.reserved_by=v_actor,false)))),false)then perform private.raise_admin_error('invalid_transition');end if;
 v_old_values:=jsonb_build_object('status',v_unit.status,'reserved_by',v_unit.reserved_by,'reserved_at',v_unit.reserved_at,'reserved_until',v_unit.reserved_until);if v_unit.status='sold'and p_new_status='available'then v_action:='unit.sold_reverted';end if;
 update public.units set status=p_new_status,reserved_by=case when p_new_status='reserved'then v_actor else null end,reserved_at=case when p_new_status='reserved'then now()else null end,reserved_until=null::timestamptz,version=version+1 where id=p_unit_id returning * into v_unit;
 insert into public.unit_status_history(unit_id,previous_status,new_status,changed_by,reason)values(v_unit.id,p_expected_status,p_new_status,v_actor,btrim(p_reason));
 insert into public.unit_audit_logs(organization_id,project_id,unit_id,action,old_values,new_values,reason,performed_by)values(v_org_id,v_unit.project_id,v_unit.id,v_action,v_old_values,jsonb_build_object('status',v_unit.status,'reserved_by',v_unit.reserved_by,'reserved_at',v_unit.reserved_at,'reserved_until',v_unit.reserved_until,'version',v_unit.version),btrim(p_reason),v_actor);return v_unit;
end$$;
